//! The wave library's samples (generated by tools/gen-wavelib.py), embedded
//! in the plugin. Layout and band-limiting are described in that script and
//! in dsp/wavelib.lib, which does the indexing.

include!("wavelib_layout.rs");

static DATA: &[u8] = include_bytes!("wavelib.bin");

/// Number of samples in the library.
pub const LEN: usize = DATA.len() / 4;

/// Sample `index` (clamped into range).
#[inline(always)]
pub fn sample(index: i32) -> f32 {
    let i = (index.max(0) as usize).min(LEN - 1) * 4;
    f32::from_le_bytes([DATA[i], DATA[i + 1], DATA[i + 2], DATA[i + 3]])
}

/// Basic shape `shape` (0 sine, 1 triangle, 2 saw, 3 square) at `phase`
/// (any value; only its fraction counts), from the copy whose harmonics
/// fit below ~20 kHz (or 0.45 x the sample rate) for a cycle playing at
/// `hz`. Linear interpolation, like the Faust wavetable reader. A negative
/// shape means "not needed" (the Dual's unselected algorithms): 0.
#[inline(always)]
pub fn basic(shape: i32, hz: f32, sample_rate: f32, phase: f32) -> f32 {
    if shape < 0 {
        return 0.0;
    }
    let limit = 20_000f32.min(0.45 * sample_rate);
    let top = LEVEL_SIZES.len() - 1;
    let level = (0..top).take_while(|&k| LEVEL_HARMONICS[k] as f32 * hz > limit).count();
    let size = LEVEL_SIZES[level];
    let base = (BASIC_BASE + shape.min(3) as usize) * WAVE_STRIDE + LEVEL_OFFSETS[level];
    let x = (phase - phase.floor()) * size as f32;
    let i = (x as usize).min(size - 1);
    let frac = x - i as f32;
    let (a, b) = (sample((base + i) as i32), sample((base + (i + 1) % size) as i32));
    a + (b - a) * frac
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn library_is_present_and_sane() {
        assert_eq!(LEN, 480_896);
        let peak = (0..LEN as i32).map(|i| sample(i).abs()).fold(0.0, f32::max);
        assert!(peak > 0.5 && peak < 1.5, "peak {peak}");
        assert_eq!(sample(-5), sample(0));
        assert_eq!(sample(i32::MAX), sample(LEN as i32 - 1));
    }

    #[test]
    fn basic_shapes_are_band_limited_and_in_phase() {
        let at = |s, hz, p| basic(s, hz, 48_000.0, p);
        // Sine and triangle start at 0 and peak a quarter of the way in.
        assert!(at(0, 100.0, 0.0).abs() < 1e-3 && (at(0, 100.0, 0.25) - 1.0).abs() < 1e-3);
        assert!(at(1, 100.0, 0.0).abs() < 0.02 && (at(1, 100.0, 0.25) - 1.0).abs() < 0.02);
        // Phase wraps.
        assert!((at(2, 100.0, 1.3) - at(2, 100.0, 0.3)).abs() < 1e-6);
        assert!((at(2, 100.0, -0.7) - at(2, 100.0, 0.3)).abs() < 1e-6);
        assert_eq!(at(-1, 100.0, 0.25), 0.0);
        // A saw at 5 kHz reads a copy with only a few harmonics: smooth,
        // so it never reaches its full-band copy's overshoot.
        let peak = (0..1000).map(|i| at(2, 5_000.0, i as f32 / 1000.0).abs()).fold(0.0, f32::max);
        assert!(peak < 1.0, "high saw still has its top harmonics ({peak})");
    }
}
